      SUBROUTINE SECORSC---- MIDPLANE-SYMMETRIC INTEGRALS OF PRODUCTS OF CHARACTERISTICC---- FUNCTIONS AND TRANSFER MATRIX ELEMENTS FOR A COMBINED-FUNCTIONC---- BENDING MAGNETC----------------------------------------------------------------------      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1F.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4B.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'HSINT.CIN'      INCLUDE 'HPINT.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TERMS.CIN'      INCLUDE 'VSINT.CIN'      INCLUDE 'VPINT.CIN'      INCLUDE 'WMN.CIN'      INCLUDE 'WM5N.CIN'C ---------------------------------------------------------------------      REAL            FMTB, GLOP      REAL            NMB, NMTB, NNM2      REAL            QUACK, RAT1, RAT2, RATIO, TMN, TNMB, TNSM, TNTMC      WM5N = 1.0 - 5.0*NB + RMPS*(2.0 - 5.0*NB)      TNMB = 2.0*NB - BEB - 1.0      NMB = NB - BEB      NMTB = NB - 2.0*BEB      TMN = 2.0 - NBC      RAT1 = ABS(SQRT(ABS(NB))*H0*L)      RAT2 = ABS(SQRT(ABS(WMN))*H0*L)      RATIO = AMAX1(RAT1,RAT2)      XPND = RATIO .LT. 0.01C      HSCX = 0.5*L*SX      HSSX = 0.5*SMLCX/WMN      IF (XPND) THEN        HSDX = 1.0/24.0*H0**2*L**4 - 1.0/360.*WMN*H0**4*L**6      ELSE        HSDX = RH*(DISN - 0.5*L*SX)/WMN      ENDIF      HSCX2 = (DISN + SX**2)/3.0      HSCSX = SX*DISN/3.0      IF (XPND) THEN        HSSX2 = 1.0/12.0*H0**2*L**4 - 1.0/72.*WMN*H0**4*L**6      ELSE        HSSX2 = (2.0*DISN - SX**2)/(3.0*WMN)      ENDIF      HSCY2 = 0.5*DISN*(1.0 + WMN/WM5N) - RH*NB*SY**2/WM5N      IF (XPND) THEN        HSCSY = 1.0/6.0*H0**2*L**3 - (NB/30. + WMN/120.)*H0**4*L**5        HSSY2 = 1.0/12.0*H0**2*L**4 - (NB/90. + WMN/360.)*H0**4*L**6        HSCDX = 1.0/24.0*H0**2*L**4 - 1.0/90.0*WMN*H0**4*L**6        HSSDX = 0.025*H*H0**3*L**5 - 1./280.*WMN*H0**6*L**7        HSDX2 = 1.0/120.0*H**2*H0**2*L**6 - 1./1120.*WMN*H0**6*L**8      ELSE        HSCSY = (CY*SY - SX)/WM5N        HSSY2 = ( - 2*DISN + SY**2)/WM5N        HSCDX = RH*( - (DISN + SX**2)/3.0 + 0.5*L*SX)/WMN        HSSDX = RH*(SX + 2.0*SX*CX - 3*L*CX)/(6.0*WMN**2)        HSDX2 = RH**2*(4.0*DISN - 3.0*L*SX + SX**2)/(3.0*WMN**2)      ENDIFC      HPCX = 0.5*(SX + L*CX)      HPSX = 0.5*L*SX      HPDX = 0.5*RH*SMLCX/WMN      HPCX2 = SX*(1.0 + 2.0*CX)/3.0      HPCSX = ( - DISN + 2.0*SX**2)/3.0      HPSX2 = 2.0*SX*DISN/3.0      HPCY2 = 0.5*SX*(1.0 + WMN/WM5N) - 2.0*RH*NB*CY*SY/WM5N      HPCSY = (WMN*DISN - 2.0*NB*SY**2)/WM5N      IF (XPND) THEN        HPSY2 = 1.0/3.0*H0**2*L**3 - (NB/15. + WMN/60.)*H0**4*L**5        HPCDX = 1.0/6.0*H0**2*L**3 - 1./15.*WMN*H0**4*L**5        HPSDX = 0.125*H0**2*L**4 - 0.025*WMN*H0**4*L**6        HPDX2 = 0.05*H**2*H0**2*L**5 - 1./140.*WMN*H0**6*L**7      ELSE        HPSY2 = 2.0*(CY*SY - SX)/WM5N        HPCDX = RH*(3.0*L*CX - 4.0*CX*SX + SX)/(6.0*WMN)        HPSDX = RH*(2.0*DISN + 3.0*L*SX - 4.0*SX**2)/(6.0*WMN)        HPDX2 = RH**2*(2.0*CX*SX + SX - 3.0*L*CX)/(3.0*WMN**2)      ENDIFC      VSCY = 0.5*SY*L      IF (NB .NE. 0.0) QUACK = (SY - L*CY)/NB      IF (NB .EQ. 0.0) QUACK = H0*H*L**3/3.0      VSSY = 0.5*QUACK/RH      VSCCM = 0.5*(1.0 - WMN/WM5N)*SX*SY + WMN*CY*DISN/WM5N      IF (XPND) THEN        VSCSM = 1.0/6.0*H0**2*L**3 - (NB/60. + WMN/40.)*H0**4*L**5        VSSCM = 1.0/6.0*H0**2*L**3 - (NB/30. + WMN/120.)*H0**4*L**5        VSSSM = 1.0/12.0*H0**2*L**4 - (NB/120. + WMN/180.)*H0**4*L**6        VSDCM = 1.0/24.0*H0**2*L**4 - (7.*NB + WMN)*H0**4*L**6/720.        VSDSM = 0.025*H*H0**3*L**5     1          - (13.*NB/5040 + WMN/1008.)*H0**6*L**7      ELSE        VSCSM = (2.0*SX*CY - SY*(1.0 + CX))/WM5N        VSSCM = 0.5*SY*(1.0 - CX)/WMN     1   + 0.5*SY*(1.0 + CX)/WM5N - SX*CY/WM5N        VSSSM = (2.0*CY*DISN - SX*SY)/WM5N        VSDCM =  RH*( - CY*DISN/WM5N + 0.5*L*SY/WMN     1   + 0.5*(1.0/WM5N - 1.0/WMN)*SX*SY)        VSDSM = (RH*SY*(1.0 + CX)/WM5N     1   - 2.0*RH*SX*CY/WM5N + 0.5*QUACK)/WMN      ENDIFC      VPCY = 0.5*(SY + L*CY)      VPSY = 0.5*L*SY      VPCCM = 0.5*(1.0 + WMN/WM5N)*SX*CY     1 - RH*NB*SY*(1.0 + CX)/WM5N      VPCSM = 0.5*(1.0 + WMN/WM5N)*SX*SY     1 - WMN*CY*DISN/WM5N      VPSCM = 0.5*(1.0 + WMN/WM5N)*CY*DISN     1 - RH*NB*SX*SY/WM5N      IF (XPND) THEN        VPSSM = 1.0/3.0*H0**2*L**3 - (NB/20. + WMN/30.)*H0**4*L**5        VPDCM = 1.0/6.0*H0**2*L**3 - (7.*NB + WMN)*H0**4*L**5/120.        VPDSM = 0.125*H0**2*L**4 - (13.*NB/720. + WMN/144.)*H0**4*L**6      ELSE        VPSSM = 0.5*SY*((1.0 - CX)/WMN - (1.0 + CX)/WM5N)     1   + SX*CY/WM5N        VPDCM = RH*(RH*NB*SY*(1.0 + CX)/(WMN*WM5N)     1   + 0.5*(SY + L*CY)/WMN     2   - 0.5*(1.0/WMN + 1.0/WM5N)*SX*CY)        VPDSM = RH*(CY*DISN/WM5N + 0.5*SY*L/WMN     1   - 0.5*(1.0/WMN + 1.0/WM5N)*SX*SY)      ENDIFC      T(1,1) = H0**2*(TNMB*H*HSCX2     1 + 0.5*WMN**2*(H0 - HEX)*HSSX2)      T(1,2) = H0*(H0*(2.0*H*TNMB - WMN*(H0 - HEX))*HSCSX     1 + SX)      T(1,3) = TNMB*H*HSSX2     1 + 0.5*(H0 - HEX)*HSCX2      T(1,6) = - 0.5*H0**2*H*(NMTB*HSCY2     1 + NB**2*RH**2*HSSY2)      T(1,9) = H*(- NMTB + NB*RH)*HSCSY      T(1,10) = - 0.5*H*(NMTB*HSSY2 + HSCY2)      T(1,16) = H*(2.0*TNMB*H0*HSCDX + TMN*H0*HSCX     1 - WMN*(H0 - HEX)*HSSX2)      T(1,17) = RH*(2.0*TNMB*HSSDX + TMN*HSSX     1 + H0*(H0 - HEX)*HSCSX)      T(1,21) = RH*(TNMB*H0*HSDX2 + H0*TMN*HSDX     1 - H0*DISN + 0.5*RH*(H0 - HEX)*HSSX2)      T(2,1) = H0**2*(TNMB*H*HPCX2     1 + 0.5*WMN**2*H0**2*(H0 - HEX)*HPSX2 + WMN*H0*SX*CX)      T(2,2) = H0**2*((2.0*H*TNMB - WMN*(H0 - HEX))*HPCSX     1 + WMN*H0*(2.0*SX**2 - DISN))      T(2,3) = TNMB*H0**2*H*HPSX2     1 + 0.5*(H0 - HEX)*HPCX2 - H0*SX*CX      T(2,6) = - 0.5*H0**2*H*(NMTB*HPCY2     1 + NB**2*RH**2*HPSY2)      T(2,9) = H*H0*(- NMTB*H0 + NB*H)*HPCSY      T(2,10) = - 0.5*H*(NMTB*HPSY2 + HPCY2)      T(2,16) = H0*H*(2.0*TNMB*HPCDX + TMN*HPCX     1 - WMN*H0*(H0 - HEX)*HPSX2 + WMN*H0**2*SX*DISN - SX*CX)      T(2,17) = H*(2.0*TNMB*H0*HPSDX + TMN*H0*HPSX     1 + (H0 - HEX)*HPCSX - H0*CX*DISN - H0*SX**2)      T(2,21) = H*(TNMB*HPDX2 + TMN*HPDX     1 - SX + 0.5*H*(H0 - HEX)*HPSX2 - H0*H*SX*DISN)      T(3,4) = H*H0**2*(NB*WMN*VSSSM - 2.0*NMB*VSCCM)      T(3,5) = - H*(NB*VSCSM + 2.0*NMB*VSSCM)      T(3,7) = - (WMN*H0*VSSCM + 2.0*NMB*H*VSCSM - H0*SY)      T(3,8) = H0*VSCCM - 2.0*NMB*H*VSSSM      T(3,18) = H*H0*(NB*VSCY - RH*NB*VSSSM     1 - 2.0*NMB*VSDCM)      T(3,19) = RH*(NB*VSSY + VSSCM - 2.0*NMB*VSDSM)      T(4,4) = H*H0**2*(NB*WMN*VPSSM - 2.0*NMB*VPCCM     1 + NB*CX*SY)      T(4,5) = - H*H0**2*(NB*VPCSM + 2.0*NMB*VPSCM     1 - NB*SX*SY)      T(4,7) = - H0**2*(WMN*H0*VPSCM + 2.0*NMB*H*VPCSM     1 - WMN*H0*CY*DISN)      T(4,8) = H0*VPCCM - 2.0*NMB*H*VPSSM - H0*SX*CY      T(4,18) = H*(NB*H0*VPCY - NB*H*VPSSM     1 - 2.0*NMB*H0*VPDCM + NB*H0**2*SY*DISP)      T(4,19) = H0*H*(NB*VPSY + VPSCM - 2.0*NMB*VPDSM     1 - CY*DISN)C      FMTB = 5.0*NB - 2.0*BEB - 3.0      NNM2 = NB*(NB + 1.0) - 2.0*BEB      TNSM = 3.0*NB**2 - 2.0*NB - 4.0*BEB + 3.0      TNTM = NB*(3.0*NB - 1.0) - 2.0*BEBC      T(5,1) = - (TNTM*(L - SX*CX)     1 + 4.0*NMB*(L - SX))*H0**2/(12.0*WMN)      T(5,2) = - 2.0*NMB*(1.0 - CX)/(3.0*WMN**2)     1 + TNTM*H0**2*SX**2/(6.0*WMN)      T(5,3) = - (2.0*(FMTB + 2.0*NMB)*(L - SX)     1 - FMTB*(L - SX*CX))/(12.0*WMN**2) - 0.25*(L + SX*CX)      T(5,16) =  - NNM2*H0*SMLCX/(2.0*WMN**2)     1 + 2.0*NMB*H0*(L - SX)/(3.0*WMN**2)     2 + TNTM*H0*(L - SX*CX)/(6.0*WMN**2) + GI2*DDISP      T(5,17) = - TNSM*H0*DISN/(3.0*WMN**2)     1  + (NNM2*H0*L*SX/2.0 - TNTM*H0*SX**2/6.0)/WMN**2 + GI2*DISP      T(5,21) = - (4.0*NMB*(L - SX)/3.0 - NNM2*SMLCX/2.0     2 + TNTM*(L - CX*SX)/12.0)/WMN**3 + GI2*(L - SX)      T(5,6) = - (2.0*BEB*(1.0 - 3.0*NB)/WM5N - NB)*H0**2     1 *(L - SX)/(2.0*WMN)     2 - ( - 2.0*BEB/WM5N + NB)*H0**2*(L - SY*CY)/4.0      T(5,9) = - (BEB/WM5N - 0.5*NB)*H0**2*SY**2     1 + 2.0*BEB*(1.0 - CX)/(WM5N*WMN)      IF (NB .NE. 0.0) GLOP = (L - SY*CY)/(2.0*NB)      IF (NB .EQ. 0.0) GLOP = H0**2*L**3/3.0      T(5,10) = - BEB*(GLOP - 2.0*(L - SX)/WMN)/WM5N     1 + (L - SX)/(2.0*WMN) - 0.25*(L + SY*CY)C      IF (RMPS .EQ. 0.0) GO TO 410      HEX = RMPS*H0      TNMB = 2.0*NB - BEB - 1.0      R(1,1) = R(1,1) + HEX*H0*(- 2.0*TNMB*HSCDX + WMN*HSSX2)      R(1,2) = R(1,2) - RMPS*(2.0*TNMB*HSSDX + H0**2*HSCSX)      R(1,6) = R(1,6)     1 - RMPS*(2.0*TNMB*H0*HSDX2 + TMN*H0*HSDX + HSSX2)      R(2,1) = R(2,1)     1 + HEX*H0*(- 2.0*TNMB*HPCDX + WMN*H0**2*HPSX2     2 + CX*SX - WMN*H0**2*SX*DISN)      R(2,2) = R(2,2)     1 - HEX*H0*(2.0*TNMB*HPSDX + HPCSX     2 - SX**2 - CX*DISN)      R(2,6) = R(2,6)     1 - HEX*(2.0*TNMB*HPDX2 + TMN*HPDX + H0*HPSX2     2 - 2.0*H0*SX*DISP)      R(3,3) = R(3,3) +     1 HEX*(NB*VSSSM + 2.0*NMB*H0*VSDCM)      R(3,4) = R(3,4) +     1 RMPS*(2.0*NMB*VSDSM - VSSCM)      R(4,3) = R(4,3) +     1 HEX*(NB*VPSSM + 2.0*NMB*H0*VPDCM - NB*H0**2*H*SY*DISN)      R(4,4) = R(4,4) +     1 HEX*H0*(2.0*NMB*VPDSM - VPSCM + CY*DISN)C  410 RETURN      END